// AGF-S2-20: QR print kit. Print pages are built in-app from the QR SVG already on screen (no external scripts);
// every user-controlled value (restaurant name, address, logo URL) is escaped before it enters the HTML.

export type PrintKitInput = {
    name: string;
    logoUrl?: string | null;
    url: string;
    /** Serialised QR <svg> from react-qr-code (generated by the app, not user input) */
    qrSvg: string;
};

export function escapeHtml(value: string): string {
    return value
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
}

/** `{safe-name}-qr.{ext}`: lower-case letters, digits and dashes only, at most 60 characters; "menu" when nothing is left. */
export function qrFileName(name: string, ext: "png" | "svg"): string {
    const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60).replace(/-+$/, "");
    return `${slug || "menu"}-qr.${ext}`;
}

function panel({ name, logoUrl, url, qrSvg }: PrintKitInput, flipped = false): string {
    // A logo that fails to load is dropped, so the name and QR still print (AC8)
    const logo = logoUrl && /^https?:\/\//i.test(logoUrl)
        ? `<img class="logo" src="${escapeHtml(logoUrl)}" alt="" onerror="this.remove()" />`
        : "";
    return `
      <div class="panel${flipped ? " flipped" : ""}">
        ${logo}
        <div class="name">${escapeHtml(name)}</div>
        <div class="scan">Scan to see our menu</div>
        <div class="qr">${qrSvg}</div>
        <div class="url">${escapeHtml(url)}</div>
      </div>`;
}

function page(title: string, pageCss: string, body: string): string {
    return `<!doctype html>
<html>
  <head>
    <meta charset="utf-8" />
    <title>${escapeHtml(title)}</title>
    <style>
      ${pageCss}
      * { box-sizing: border-box; }
      body { margin: 0; font-family: Arial, Helvetica, sans-serif; color: #111; }
      .panel { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4mm; text-align: center; }
      .logo { max-width: 28mm; max-height: 28mm; object-fit: contain; }
      .name { font-size: 20pt; font-weight: 700; word-break: break-word; }
      .scan { font-size: 13pt; color: #333; }
      /* white quiet zone around the code; at least 6 cm wide so it scans from a table */
      .qr { width: 70mm; height: 70mm; padding: 5mm; background: #fff; }
      .qr svg { width: 100%; height: 100%; display: block; }
      .url { font-size: 8pt; color: #555; word-break: break-all; max-width: 110mm; }
    </style>
  </head>
  <body>
    ${body}
    <script>window.onload = function () { window.focus(); window.print(); };</script>
  </body>
</html>`;
}

/** A5 portrait: one panel per page. */
export function a5SheetHtml(input: PrintKitInput): string {
    return page(
        `${input.name} – QR menu (A5)`,
        `@page { size: A5 portrait; margin: 10mm; }
      .sheet { min-height: calc(210mm - 20mm); display: flex; align-items: center; justify-content: center; }`,
        `<div class="sheet">${panel(input)}</div>`,
    );
}

/**
 * A4 landscape table tent: two identical panels with a fold line between them. The top panel is upside down, so
 * after folding along the line and standing the card up, both sides read the right way round.
 */
export function tableTentHtml(input: PrintKitInput): string {
    return page(
        `${input.name} – QR menu (table tent)`,
        `@page { size: A4 landscape; margin: 0; }
      .tent { width: 297mm; height: 210mm; display: flex; flex-direction: column; }
      .tent .panel { flex: 1; gap: 2.5mm; }
      .tent .qr { width: 58mm; height: 58mm; padding: 4mm; }
      .flipped { transform: rotate(180deg); }
      .fold { border-top: 0.4mm dashed #888; position: relative; }
      .fold span { position: absolute; right: 8mm; top: -4mm; font-size: 7pt; color: #888; background: #fff; padding: 0 2mm; }`,
        `<div class="tent">${panel(input, true)}<div class="fold"><span>Fold here</span></div>${panel(input)}</div>`,
    );
}
